def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    yesterday_bids = []
    threat_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = prev.get('bid', 0)
            yesterday_bids.append(b)
            if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                threat_bids.append(b)

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    moderate_prev = 0.0
    non_extreme = [b for b in threat_bids if b <= 100]
    if non_extreme:
        moderate_prev = max(non_extreme)
    elif threat_bids:
        moderate_prev = min(threat_bids)

    total_players = 1 + len(alive)
    guaranteed_units = int(supply // WATER_REQ)
    scarcity = guaranteed_units < total_players
    severe_scarcity = guaranteed_units <= 1
    high_supply = supply >= 22

    critical = hp <= 2 or no_water_days >= 2
    urgent = hp <= 4 or no_water_days >= 1

    if critical:
        bid = min(budget, max(92.0, highest_prev + 3.0, DAILY_SALARY * 1.18))
        return float(bid)

    if severe_scarcity:
        if urgent:
            bid = max(88.0, moderate_prev + 2.5)
        else:
            bid = 26.0 if high_supply else 34.0
            if desperate_count >= 2:
                bid += 6.0
            if rich_count >= 2:
                bid += 4.0
        return float(min(budget, bid))

    if scarcity:
        if urgent:
            bid = max(74.0, moderate_prev + 2.0)
        else:
            if moderate_prev > 0:
                bid = max(46.0, min(72.0, moderate_prev + 1.5))
            else:
                bid = 49.0
            if high_supply:
                bid -= 6.0
        return float(min(budget, bid))

    if high_supply:
        bid = 18.0
    else:
        bid = 28.0

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid -= 4.0

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
