def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            pass

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent trace (immediate reaction signal)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid depends on our HP pressure
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 3:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # Use yesterday's max/percentile to avoid overpaying while beating low bids
    if prev_bids:
        y_max = max(prev_bids)
        y_min = min(prev_bids)
        # If someone was already near salary, expect competition; nudge upward.
        if y_max >= DAILY_SALARY * 0.85:
            base = max(base, DAILY_SALARY * 0.62)
        # If competition was generally low, we can stay closer to base.
        if y_min < DAILY_SALARY * 0.55 and y_max < DAILY_SALARY * 0.7:
            base = min(base, DAILY_SALARY * 0.6)

        # Target just above the lower end to beat low bidders (Bob-like behavior)
        # Use median as a robust anchor.
        sorted_b = sorted(prev_bids)
        mid = sorted_b[len(sorted_b)//2]
        # Bid slightly above median but capped by our base.
        target = min(base, mid + 5.0)
    else:
        target = base

    # Supply effect: when supply is smaller, winning water is more valuable.
    # Our requirement is 7; supply 15-25 means we likely can win with moderate bids.
    if supply <= 17.0:
        target *= 1.08
    elif supply >= 22.0:
        target *= 0.98

    # Final clamp to budget and non-negative
    bid = max(0.0, min(my_budget, target))
    # Avoid bidding extremely tiny amounts that risk losing when HP is low
    if bid < DAILY_SALARY * 0.25 and (my_hp <= 3 or my_no_water_days >= 2):
        bid = min(my_budget, DAILY_SALARY * 0.35)

    return float(bid)
